+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days (ledger refs `sale:<ticket>`, booked at the time of sale)
+ * against actual use (every consume movement), for items where either is above 0.
+ */
+export function varianceReport(store, from, to) {
+  const byItem = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = new Date(m.at).toISOString().slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    const line = byItem.get(batch.itemId) ?? { theoretical: 0, actual: 0 };
+    line.actual += m.qty;
+    if (m.ref.startsWith("sale:")) line.theoretical += m.qty;
+    byItem.set(batch.itemId, line);
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...byItem]
+    .map(([itemId, l]) => ({ itemId, theoretical: r3(l.theoretical), actual: r3(l.actual), difference: r3(l.actual - l.theoretical) }))
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
